import sys,difflib,re
lines=open(sys.argv[1],encoding='utf-8').read().split('\n')
minus=[];plus=[];out=[]
def flush():
    global minus,plus
    for i in range(max(len(minus),len(plus))):
        a=minus[i] if i<len(minus) else ''
        b=plus[i] if i<len(plus) else ''
        ta=re.findall(r'\S+|\s+',a);tb=re.findall(r'\S+|\s+',b)
        sm=difflib.SequenceMatcher(None,ta,tb,autojunk=False)
        s=''
        for op,i1,i2,j1,j2 in sm.get_opcodes():
            if op=='equal': 
                t=''.join(ta[i1:i2]); s+= t if len(t)<160 else t[:70]+' ... '+t[-70:]
            else:
                if i2>i1: s+='[-'+''.join(ta[i1:i2])+'-]'
                if j2>j1: s+='{+'+''.join(tb[j1:j2])+'+}'
        print('CHG:',s);print()
    minus=[];plus=[]
for l in lines:
    if l.startswith('@@'):
        flush();print(l[:60])
    elif l.startswith('---') or l.startswith('+++') or l.startswith('diff') or l.startswith('index'): pass
    elif l.startswith('-'): minus.append(l[1:])
    elif l.startswith('+'): plus.append(l[1:])
    else: flush()
flush()
EOF
